wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let kept = composed.entries.iter().filter(|e| e.kept).count();

        let overview: String = composed.overview.chars().take(500).collect();
        let message = format!(
            "Digest {} ({} kept of {} considered): {}",
            composed.date,
            kept,
            composed.considered.len(),
            overview,
        );

        let published = crate::aap::caps::notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
